const body = $input.first().json.body || $input.first().json;
const payment = body.payload?.payment?.entity;
const bookingRef = payment?.notes?.booking_ref || body.booking_ref;
const paymentId = payment?.id || body.payment_id || `pay_${Date.now()}`;
const customerPhone = payment?.contact || body.customer_phone || '+919876543210';

return {
  json: {
    bookingRef,
    paymentId,
    customerPhone: customerPhone.startsWith('+') ? customerPhone : `+${customerPhone}`,
    amountPaise: payment?.amount,
    amountRupees: payment?.amount ? payment.amount / 100 : 1800,
    method: payment?.method || 'upi'
  }
};
